import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundTextureShift{ActionID: packet.TextureShiftActionStart, CollectionName: "shift", FromStep:
# "dawn", ToStep: "dusk", AllSteps: []string{"dawn", "noon", "dusk"}, CurrentLengthTicks: 200, TotalLengthTicks:
# 400, Enabled: true}
SHIFT = bytes.fromhex("02057368696674046461776e046475736b03046461776e046e6f6f6e046475736bc801900301")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundTextureShift{ActionID: packet.TextureShiftActionSetEnabled}
EMPTY = bytes.fromhex("0300000000000000")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundTextureShift{ActionID: packet.TextureShiftActionSync, CurrentLengthTicks: 128, TotalLengthTicks:
# 1, Enabled: true}
SYNC = bytes.fromhex("040000000080010101")

GOLDENS = (
    [
        pytest.param(
            v.ClientboundTextureShiftPacket(
                action=v.ClientboundTextureShiftPacket.Action.START,
                collection_name="shift",
                from_step="dawn",
                to_step="dusk",
                all_steps=["dawn", "noon", "dusk"],
                current_length_in_ticks=200,
                total_length_in_ticks=400,
                enabled=True,
            ),
            SHIFT,
            id=f"{v.__name__.rpartition('.')[2]}-start",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ClientboundTextureShiftPacket(action=v.ClientboundTextureShiftPacket.Action.SET_ENABLED),
            EMPTY,
            id=f"{v.__name__.rpartition('.')[2]}-no-steps",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ClientboundTextureShiftPacket(
                action=v.ClientboundTextureShiftPacket.Action.SYNC,
                current_length_in_ticks=128,
                total_length_in_ticks=1,
                enabled=True,
            ),
            SYNC,
            id=f"{v.__name__.rpartition('.')[2]}-varint-tick-counts",
        )
        for v in VERSIONS
    ]
)


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_clientbound_texture_shift_is_packet_336(version):
    assert version.PACKETS[336] is version.ClientboundTextureShiftPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_texture_shift_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_texture_shift_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
